 import { MeshBasicNodeMaterial } from 'three/webgpu';
import {
  uv,
  vec2,
  vec3,
  mix,
  add,
  mul,
  smoothstep,
  fract,
  sin,
  dot,
  clamp,
  uniform,
  texture,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { PlaneGeometry, Mesh, Group, Color } = ctx.THREE;

  const group = new Group();
  group.userData.isDisposed = false;
  group.userData.handlers = {};

  const visualSpec = config.intent?.visualSpec ?? {};
  const colors = visualSpec.colors ?? config.colors ?? {};
  const imageUrl = config.imageUrl ?? visualSpec.imageUrl;

  const ink = new Color(colors.ink ?? '#16161d');
  const paper = new Color(colors.paper ?? '#e8ecf2');
  const accent = new Color(colors.accent ?? '#ff2a38');
  const surface = new Color(colors.surface ?? '#0b0b10');

  const uInk = uniform(ink);
  const uPaper = uniform(paper);
  const uAccent = uniform(accent);
  const uSurface = uniform(surface);

  const width = 0.96;
  const height = 0.6;
  const geometry = new PlaneGeometry(width, height);

  function buildColorNode(tex) {
    const st = uv();
    const v = st.y;

    const grad = mix(uSurface, uInk, smoothstep(0.0, 1.0, v));

    let base = grad;
    if (tex) {
      const texColor = texture(tex, st).rgb;
      base = mix(texColor, grad, 0.55);
    }

    const paperA = smoothstep(0.82, 1.0, v);
    const paperB = smoothstep(0.0, 0.18, st.x);
    const paperMask = mul(mul(paperA, paperB), 0.06);
    base = mix(base, uPaper, paperMask);

    const accentMask = mul(smoothstep(0.06, 0.0, v), 0.35);
    base = mix(base, uAccent, accentMask);

    const noise = fract(mul(sin(dot(st, vec2(12.9898, 78.233))), 43758.5453));
    const grain = mul(vec3(noise), 0.03);

    return clamp(add(base, grain), 0.0, 1.0);
  }

  const material = new MeshBasicNodeMaterial();
  material.colorNode = buildColorNode(null);

  const mesh = new Mesh(geometry, material);
  mesh.name = config.id ?? 'features-card-3';
  group.add(mesh);

  if (imageUrl) {
    ctx.textureLoader
      .loadTexture(imageUrl)
      .then((tex) => {
        if (group.userData.isDisposed) {
          tex.dispose();
          return;
        }
        group.userData.texture = tex;
        material.colorNode = buildColorNode(tex);
        material.needsUpdate = true;
      })
      .catch(() => {
        // texture failed; gradient remains
      });
  }

  group.userData.cleanup = () => {
    group.userData.isDisposed = true;
    if (group.userData.texture) {
      group.userData.texture.dispose();
      group.userData.texture = null;
    }
    material.dispose();
    geometry.dispose();

    // no primitive timelines, but include entry point
    if (group.userData.timelines) {
      group.userData.timelines.forEach((tl) => tl?.kill());
    }
  };

  return group;
}
